// WhatsApp only allows free-form messages within 24h of the customer's last message
// (the customer service window); after that only a pre-approved template may be sent.
const l = $json;
const action = l.source === 'whatsapp' ? (l.in_window ? 'send' : 'template_needed') : 'manual';
return { json: { ...l, action, wa_to: l.contact.replace(/^\+/, '') } };
